import SwiftUI

extension Theme {
    /// Semantic colors. Each is a color set in Assets.xcassets with light and dark
    /// variants; `ColorResource` symbols are generated by the asset catalog compiler.
    enum Colors {
        /// Brand accent: primary buttons, selection, focus.
        static let accent = Color(.accent)
        /// Window background.
        static let background = Color(.background)
        /// Cards, sheets and table backgrounds that sit on `background`.
        static let surface = Color(.surface)
        static let textPrimary = Color(.textPrimary)
        static let textSecondary = Color(.textSecondary)
        /// Synced, verified, healthy.
        static let success = Color(.success)
        /// Needs attention: drift, missing values, weak settings.
        static let warning = Color(.warning)
        /// Destructive actions and failures.
        static let danger = Color(.danger)
        /// Local changes that are not yet on GitHub.
        static let pending = Color(.pending)
    }
}
